INSERT INTO jobs (id, organization_id, title, summary, plain_summary, description, region, city, work_mode, employment_type,
                  salary_text, deadline, status, custom_questions) VALUES
 ('0c000000-0000-4000-8000-000000000001', '0a000000-0000-4000-8000-000000000001',
  'Customer Support Agent (Amharic and English)',
  'Answer customer questions by chat and phone for a growing digital services company.',
  'You will help customers by answering their questions. You will use chat and phone. You need to speak Amharic and English.',
  'Kidame Digital Services is hiring customer support agents. You will answer customer questions through chat and phone, record issues in our help-desk system, and pass difficult cases to the right team. Training is provided in the first two weeks. We welcome applicants who use screen readers or other assistive technology; our help-desk software works with NVDA and JAWS.',
  'ADDIS_ABABA', 'Addis Ababa', 'HYBRID', 'FULL_TIME', 'ETB 12,000 - 15,000 per month', CURRENT_DATE + 45, 'PUBLISHED',
  '[{"id":"custom1","label":"Which languages can you use with customers?","type":"textarea","required":true,"options":[]},{"id":"custom2","label":"Have you worked in customer service before?","type":"radio","required":true,"options":["Yes","No"]}]'),
 ('0c000000-0000-4000-8000-000000000002', '0a000000-0000-4000-8000-000000000001',
  'Junior Web Developer (Remote)',
  'Build and maintain accessible websites with HTML, CSS and JavaScript.',
  'You will make websites. You will work from home. You need to know basic HTML, CSS and JavaScript.',
  'Join a small team building websites for local businesses. You will write HTML, CSS and JavaScript, test pages with a keyboard and a screen reader, and fix reported problems. Work is fully remote with flexible hours. A laptop and internet allowance are provided.',
  'ADDIS_ABABA', NULL, 'REMOTE', 'FULL_TIME', 'ETB 18,000 - 24,000 per month', CURRENT_DATE + 60, 'PUBLISHED',
  '[{"id":"custom1","label":"Share a link to something you have built, or describe a project.","type":"textarea","required":false,"options":[]}]'),
 ('0c000000-0000-4000-8000-000000000003', '0a000000-0000-4000-8000-000000000002',
  'Farm Records Assistant',
  'Keep simple digital records of harvests, sales and member payments.',
  'You will write down farm information on a tablet. This includes harvests and sales. You need basic reading and counting skills.',
  'Horizon Agro Cooperative needs an assistant to record harvest weights, sales and payments to members using a tablet application. You will work in the cooperative office in Adama, with occasional visits to member farms (transport provided). The office is on the ground floor with step-free access.',
  'OROMIA', 'Adama', 'ONSITE', 'FULL_TIME', 'ETB 8,000 per month', CURRENT_DATE + 30, 'PUBLISHED', '[]'),
 ('0c000000-0000-4000-8000-000000000004', '0a000000-0000-4000-8000-000000000003',
  'Community Health Data Clerk (Part-time)',
  'Enter health-visit records into the district database, mornings only.',
  'You will type health information into a computer. You work in the mornings only.',
  'Abay Community Health is looking for a part-time data clerk to enter community health-visit records into the district system. Hours are 8:30 to 12:30, Monday to Friday. Written instructions are provided for every task and a quiet workspace is available.',
  'AMHARA', 'Bahir Dar', 'ONSITE', 'PART_TIME', 'ETB 6,500 per month', CURRENT_DATE + 21, 'PUBLISHED', '[]'),
 ('0c000000-0000-4000-8000-000000000005', '0a000000-0000-4000-8000-000000000003',
  'Sign Language Health Educator',
  'Deliver health education sessions to Deaf community members in Ethiopian Sign Language.',
  'You will teach health topics to Deaf people. You will use Ethiopian Sign Language.',
  'We are hiring an educator fluent in Ethiopian Sign Language to run health education sessions with Deaf community members and to help our clinic staff communicate better. Deaf applicants are strongly encouraged to apply. Interviews will be held with a sign language interpreter.',
  'AMHARA', 'Bahir Dar', 'ONSITE', 'CONTRACT', NULL, CURRENT_DATE + 40, 'PUBLISHED', '[]'),
 ('0c000000-0000-4000-8000-000000000006', '0a000000-0000-4000-8000-000000000001',
  'Data Entry Internship',
  'A 3-month paid internship entering and checking data. Training provided.',
  'This is a short paid job for 3 months. You will type and check information. We will train you.',
  'A three-month paid internship for recent graduates and learners. You will enter and check data, learn spreadsheet basics and shadow our operations team. Flexible start and finish times. Remote work is possible after the first month.',
  'ADDIS_ABABA', 'Addis Ababa', 'HYBRID', 'INTERNSHIP', 'ETB 5,000 per month stipend', CURRENT_DATE + 35, 'PUBLISHED', '[]'),
 ('0c000000-0000-4000-8000-000000000007', '0a000000-0000-4000-8000-000000000002',
  'Mobile Money Agent Coordinator',
  'Support village mobile-money agents by phone and SMS.',
  'You will help mobile money agents in villages. You will use phone calls and SMS.',
  'Coordinate a network of mobile-money agents in rural Oromia. Most work is done by phone and SMS from home, with one office day per month. Afaan Oromo is required; Amharic is an advantage.',
  'OROMIA', NULL, 'REMOTE', 'PART_TIME', NULL, CURRENT_DATE + 50, 'PUBLISHED', '[]');

INSERT INTO job_accommodations (job_id, categories, workplace_accommodations, interview_arrangements, flexible_working,
                                assistive_technology, application_accessibility, contact_name, contact_email, contact_phone) VALUES
 ('0c000000-0000-4000-8000-000000000001', '["SCREEN_READER","ASSISTIVE_TECH","ACCESSIBLE_BUILDING","ACCESSIBLE_INTERVIEW","EXTRA_TIME"]',
  'Step-free office with an accessible toilet. Adjustable desks are available.',
  'Interviews can be online or in person. We can give extra time and share questions in writing beforehand.',
  'Two days per week can be worked from home after training.',
  'Help-desk software tested with NVDA and JAWS. Screen magnification software can be installed.',
  'You can apply in Amharic or English. Ask us if you need another format.',
  'Accessibility contact (Demo)', 'access@example.com', NULL),
 ('0c000000-0000-4000-8000-000000000002', '["REMOTE_WORK","FLEXIBLE_HOURS","SCREEN_READER","ACCESSIBLE_INTERVIEW","WRITTEN_INSTRUCTIONS"]',
  'Fully remote role.', 'Online interview with captions turned on. A take-home task replaces live coding if you prefer.',
  'Choose your own working hours within a 40-hour week.', 'Laptop provided; you may use your own assistive technology.',
  'Answers can be written or recorded as voice.', 'Hiring team (Demo)', 'jobs@example.com', NULL),
 ('0c000000-0000-4000-8000-000000000003', '["ACCESSIBLE_BUILDING","TRANSPORT","WRITTEN_INSTRUCTIONS"]',
  'Ground-floor office with step-free access.', 'Interview at the office or by phone.', NULL, NULL,
  'You can apply with help from a family member or our staff.', 'Office manager (Demo)', NULL, '+251911000000'),
 ('0c000000-0000-4000-8000-000000000004', '["QUIET_SPACE","WRITTEN_INSTRUCTIONS","FLEXIBLE_HOURS","EXTRA_TIME"]',
  'A quiet workspace is available.', 'You can bring a support person to the interview.', 'Start time can be adjusted by one hour.',
  NULL, NULL, 'HR (Demo)', 'hr@example.com', NULL),
 ('0c000000-0000-4000-8000-000000000005', '["SIGN_LANGUAGE","CAPTIONS","ACCESSIBLE_INTERVIEW","ACCESSIBLE_BUILDING"]',
  'Sign language interpreters are available for team meetings.', 'Interviews with an Ethiopian Sign Language interpreter.',
  NULL, 'Video calls with captions.', 'You can send a signed video instead of a written answer.', 'HR (Demo)', 'hr@example.com', NULL),
 ('0c000000-0000-4000-8000-000000000006', '["FLEXIBLE_HOURS","REMOTE_WORK","WRITTEN_INSTRUCTIONS","ASSISTIVE_TECH"]',
  NULL, 'Short informal online interview.', 'Flexible start and finish times.', 'Screen readers and magnifiers supported.',
  NULL, 'Internship coordinator (Demo)', 'interns@example.com', NULL),
 ('0c000000-0000-4000-8000-000000000007', '["REMOTE_WORK","FLEXIBLE_HOURS"]',
  'Work from home with one office day per month.', 'Phone interview.', 'Flexible hours.', NULL, NULL,
  'Coordinator (Demo)', NULL, '+251911000001');

-- ---------------------------------------------------------------- approved help content
-- English is the source text (reviewed = TRUE by the project team).
-- Other languages are DRAFT translations (reviewed = FALSE) and must be checked by fluent speakers.

INSERT INTO help_articles (slug, locale, topic, title, body, keywords, reviewed) VALUES
('how-registration-works','en','registration','How registration works',
$$Registration asks one question at a time. Answer the question, then choose "Next". You can go back to change an answer at any time. At the end you will see all your answers and can change them before you finish. There is no time limit.$$,
'["register","registration","sign up","account","start","question","next","back"]', TRUE),
('why-we-ask','en','privacy','Why we ask for personal information',
$$We only ask for information that helps you create an account, apply for jobs or get support. Each question has a "Why we ask" note. Questions marked "optional" can be skipped. We never ask for a medical diagnosis.$$,
'["why","personal","information","optional","skip","diagnosis","data"]', TRUE),
('your-privacy','en','privacy','Your privacy and what employers see',
$$Employers only see the profile sections you choose to share when you apply. Your support preferences and private support requests are never shown to employers unless you choose to share a note. You can download or delete your data from Account settings.$$,
'["privacy","private","share","employer","consent","delete","download"]', TRUE),
('voice-input','en','voice','Using voice input',
$$Choose "Speak your answer" next to a question and speak clearly. Your words appear as text so you can check and correct them. Nothing is saved until you choose "Use this text". Typing always works too. Some browsers send your voice to an online speech service to turn it into text.$$,
'["voice","speak","microphone","speech","talk","dictate"]', TRUE),
('read-aloud','en','accessibility','Listening to questions',
$$Choose "Listen" to hear a question or message read aloud. You can pause, continue and stop at any time. If your phone has no voice for your language, the text stays on screen. If you use a screen reader, you may not need this feature.$$,
'["listen","read aloud","audio","hear","sound","pause","stop"]', TRUE),
('accessibility-settings','en','accessibility','Changing how ACCESSFLOW looks and works',
$$Open "Accessibility settings" to make text larger, turn on high contrast, use simpler words, reduce motion, show captions, show read-aloud buttons, or choose your language. Changes apply immediately and are saved for next time.$$,
'["settings","text size","bigger","contrast","simple","language","motion","captions","keyboard"]', TRUE),
('identity-options','en','identity','If you do not have a national ID',
$$You can use a kebele ID, passport, refugee ID or another document. If you have no document, a partner organisation can refer you, or you can choose "Refer me" so a partner contacts you. Every option is checked by trained staff. We only keep the last 4 characters of your document number.$$,
'["id","identity","document","refugee","passport","kebele","fayda","referral","refer me","verification"]', TRUE),
('private-support','en','support','Asking for private support',
$$You can ask for help at any time without medical proof. Tell us what would help, and how we should contact you. Only trained ACCESSFLOW support staff can read your request. A person will reply to you.$$,
'["help","support","assistance","human","person","contact","private"]', TRUE),
('save-and-resume','en','progress','Saving and continuing later',
$$Your answers are saved automatically while you work. If your connection drops, your answers stay on this device and are sent when you are back online. To continue later, sign in again and choose "Continue" on your dashboard. On a shared phone, turn on "Shared device" so answers are not stored on the phone.$$,
'["save","resume","continue","later","offline","internet","connection","draft"]', TRUE),
('applying-for-jobs','en','application','Applying for a job',
$$Open a job and choose "Apply". Some answers are filled in from your profile; you can change them. You choose which parts of your profile the employer sees. Before sending, you review every answer. After sending, you can follow your application status on your dashboard.$$,
'["apply","application","job","submit","review","status","employer"]', TRUE),
('fixing-errors','en','errors','When an answer has a problem',
$$If an answer needs fixing, a message appears under the question explaining what to change. The message is also announced to screen readers. Change the answer and choose "Next" again. If you are stuck, choose "Get help".$$,
'["error","problem","wrong","invalid","fix","message","required"]', TRUE),
('job-support-filter','en','jobs','Finding jobs with the support you need',
$$On the jobs page you can filter by workplace support, such as sign language, remote work or screen reader support. This filter is private: it is not saved and employers never see it. You do not need to tell anyone about a disability.$$,
'["filter","support","accommodation","sign language","remote","find","search","jobs"]', TRUE),

-- Amharic (draft translation)
('how-registration-works','am','registration','ምዝገባ እንዴት ይሠራል',
$$ምዝገባው አንድ ጥያቄ በአንድ ጊዜ ይጠይቃል። ጥያቄውን ይመልሱ፣ ከዚያም "ቀጣይ" ይምረጡ። በማንኛውም ጊዜ ወደ ኋላ ተመልሰው መልስዎን መቀየር ይችላሉ። በመጨረሻ ሁሉንም መልሶችዎን አይተው ከመጨረስዎ በፊት መቀየር ይችላሉ። የጊዜ ገደብ የለም።$$,
'["ምዝገባ","መመዝገብ","መለያ","ጥያቄ","ቀጣይ"]', FALSE),
('why-we-ask','am','privacy','የግል መረጃ ለምን እንጠይቃለን',
$$መለያ ለመፍጠር፣ ለሥራ ለማመልከት ወይም ድጋፍ ለማግኘት የሚረዳ መረጃ ብቻ እንጠይቃለን። እያንዳንዱ ጥያቄ "ለምን እንጠይቃለን" የሚል ማብራሪያ አለው። "አማራጭ" የተባሉ ጥያቄዎችን መዝለል ይችላሉ። የሕክምና ምርመራ ውጤት በፍጹም አንጠይቅም።$$,
'["ለምን","የግል","መረጃ","አማራጭ"]', FALSE),
('your-privacy','am','privacy','የእርስዎ ግላዊነት እና ቀጣሪዎች የሚያዩት',
$$ቀጣሪዎች የሚያዩት ሲያመለክቱ እንዲያዩ የመረጧቸውን የመገለጫ ክፍሎች ብቻ ነው። የድጋፍ ምርጫዎችዎ እና የግል የድጋፍ ጥያቄዎችዎ እርስዎ ካልመረጡ በስተቀር ለቀጣሪዎች አይታዩም። መረጃዎን ከመለያ ቅንብሮች ማውረድ ወይም መሰረዝ ይችላሉ።$$,
'["ግላዊነት","ማጋራት","ቀጣሪ","ስምምነት","መሰረዝ"]', FALSE),
('voice-input','am','voice','በድምፅ መመለስ',
$$ከጥያቄው አጠገብ "መልስዎን ይናገሩ" ይምረጡ እና በግልጽ ይናገሩ። ቃላትዎ እንደ ጽሑፍ ይታያሉ፤ ማረጋገጥ እና ማስተካከል ይችላሉ። "ይህን ጽሑፍ ተጠቀም" እስኪመርጡ ድረስ ምንም አይቀመጥም። መጻፍም ሁልጊዜ ይቻላል። አንዳንድ አሳሾች ድምፅዎን ወደ ጽሑፍ ለመቀየር ወደ የመስመር ላይ አገልግሎት ይልካሉ።$$,
'["ድምፅ","መናገር","ማይክሮፎን","ንግግር"]', FALSE),
('read-aloud','am','accessibility','ጥያቄዎችን ማዳመጥ',
$$ጥያቄ ወይም መልእክት ጮክ ብሎ እንዲነበብ "አዳምጥ" ይምረጡ። በማንኛውም ጊዜ ማቆም፣ መቀጠል እና መጨረስ ይችላሉ። ስልክዎ ለቋንቋዎ ድምፅ ከሌለው ጽሑፉ በማያ ገጹ ላይ ይቆያል።$$,
'["ማዳመጥ","ጮክ ብሎ","ድምፅ","ማቆም"]', FALSE),
('accessibility-settings','am','accessibility','የተደራሽነት ቅንብሮችን መቀየር',
$$"የተደራሽነት ቅንብሮች" ን ይክፈቱ፤ ጽሑፍን ማሳደግ፣ ከፍተኛ ንፅፅር ማብራት፣ ቀላል ቃላት መጠቀም፣ እንቅስቃሴን መቀነስ፣ የጽሑፍ ማብራሪያዎችን ማሳየት ወይም ቋንቋ መምረጥ ይችላሉ። ለውጦች ወዲያውኑ ይተገበራሉ እና ይቀመጣሉ።$$,
'["ቅንብሮች","የጽሑፍ መጠን","ንፅፅር","ቀላል","ቋንቋ"]', FALSE),
('identity-options','am','identity','ብሔራዊ መታወቂያ ከሌለዎት',
$$የቀበሌ መታወቂያ፣ ፓስፖርት፣ የስደተኛ መታወቂያ ወይም ሌላ ሰነድ መጠቀም ይችላሉ። ምንም ሰነድ ከሌለዎት አጋር ድርጅት ሊጠቁምዎ ይችላል፣ ወይም "ጠቁሙኝ" ን መምረጥ ይችላሉ። እያንዳንዱ አማራጭ በሰለጠኑ ሠራተኞች ይረጋገጣል። የሰነድ ቁጥርዎን የመጨረሻ 4 ፊደላት ብቻ እናስቀምጣለን።$$,
'["መታወቂያ","ሰነድ","ስደተኛ","ፓስፖርት","ቀበሌ","ፋይዳ","ጥቆማ"]', FALSE),
('private-support','am','support','የግል ድጋፍ መጠየቅ',
$$ያለ ሕክምና ማስረጃ በማንኛውም ጊዜ እርዳታ መጠየቅ ይችላሉ። ምን እንደሚረዳዎት እና እንዴት እንድናገኝዎ እንደሚፈልጉ ይንገሩን። ጥያቄዎን ማንበብ የሚችሉት የሰለጠኑ የACCESSFLOW ድጋፍ ሠራተኞች ብቻ ናቸው። አንድ ሰው ይመልስልዎታል።$$,
'["እርዳታ","ድጋፍ","ሰው","ግንኙነት"]', FALSE),
('save-and-resume','am','progress','ማስቀመጥ እና በኋላ መቀጠል',
$$መልሶችዎ በሚሠሩበት ጊዜ በራስ-ሰር ይቀመጣሉ። ግንኙነትዎ ቢቋረጥ መልሶችዎ በዚህ መሣሪያ ላይ ይቆያሉ እና ተመልሰው ሲገናኙ ይላካሉ። በኋላ ለመቀጠል እንደገና ይግቡ እና በዳሽቦርድዎ ላይ "ቀጥል" ይምረጡ።$$,
'["ማስቀመጥ","መቀጠል","በኋላ","ኢንተርኔት","ግንኙነት"]', FALSE),
('applying-for-jobs','am','application','ለሥራ ማመልከት',
$$ሥራ ይክፈቱ እና "አመልክት" ይምረጡ። አንዳንድ መልሶች ከመገለጫዎ ይሞላሉ፤ መቀየር ይችላሉ። ቀጣሪው የትኞቹን የመገለጫዎ ክፍሎች እንደሚያይ እርስዎ ይመርጣሉ። ከመላክዎ በፊት ሁሉንም መልሶች ይገመግማሉ። ከላኩ በኋላ የማመልከቻዎን ሁኔታ በዳሽቦርድዎ መከታተል ይችላሉ።$$,
'["ማመልከት","ማመልከቻ","ሥራ","መላክ","ሁኔታ"]', FALSE),
('fixing-errors','am','errors','መልስ ችግር ሲኖረው',
$$መልስ መስተካከል ካለበት ምን መቀየር እንዳለብዎ የሚያብራራ መልእክት ከጥያቄው በታች ይታያል። መልሱን ይቀይሩ እና እንደገና "ቀጣይ" ይምረጡ። ከተቸገሩ "እርዳታ ያግኙ" ይምረጡ።$$,
'["ስህተት","ችግር","ማስተካከል","መልእክት"]', FALSE),
('job-support-filter','am','jobs','የሚፈልጉትን ድጋፍ ያላቸውን ሥራዎች ማግኘት',
$$በሥራዎች ገጽ ላይ እንደ ምልክት ቋንቋ፣ ከቤት መሥራት ወይም የስክሪን አንባቢ ድጋፍ ባሉ የሥራ ቦታ ድጋፎች ማጣራት ይችላሉ። ይህ ማጣሪያ የግል ነው፤ አይቀመጥም፣ ቀጣሪዎችም አያዩትም።$$,
'["ማጣሪያ","ድጋፍ","ምልክት ቋንቋ","ሥራ","ፍለጋ"]', FALSE),

-- Afaan Oromo (draft translation)
('how-registration-works','om','registration','Galmeen akkamitti hojjeta',
$$Galmeen gaaffii tokko yeroo tokkotti gaafata. Gaaffii deebisaatii "Itti aanu" filadhaa. Yeroo kamiyyuu duubatti deebitanii deebii keessan jijjiiruu dandeessu. Dhuma irratti deebii keessan hunda ilaaluu fi jijjiiruu dandeessu. Daangaan yeroo hin jiru.$$,
'["galmee","galmaa''uu","herrega","gaaffii"]', FALSE),
('why-we-ask','om','privacy','Odeeffannoo dhuunfaa maaliif gaafanna',
$$Odeeffannoo herrega uumuuf, hojiif iyyachuuf ykn deeggarsa argachuuf isin gargaaru qofa gaafanna. Gaaffiin tokkoon tokkoon isaa ibsa "Maaliif gaafanna" qaba. Gaaffiiwwan "filannoo" jedhaman dabruu dandeessu. Bu''aa qorannoo yaalaa gonkumaa hin gaafannu.$$,
'["maaliif","dhuunfaa","odeeffannoo","filannoo"]', FALSE),
('your-privacy','om','privacy','Dhuunfaa keessan fi kan qacaraan argu',
$$Qacaraan kutaa piroofaayilii keessanii isin qooduuf filattan qofa argu. Filannoon deeggarsaa fi gaaffiin deeggarsa dhuunfaa keessan qacaraaf hin mul''atu. Odeeffannoo keessan buufachuu ykn haquu dandeessu.$$,
'["dhuunfaa","qooduu","qacaraa","haquu"]', FALSE),
('voice-input','om','voice','Sagaleedhaan deebisuu',
$$Gaaffii bira "Deebii keessan dubbadhaa" filadhaa ifatti dubbadhaa. Jechoonni keessan barreeffamaan mul''atu; mirkaneessuu fi sirreessuu dandeessu. Hanga "Barreeffama kana fayyadami" filattanitti homtuu hin olkaa''amu. Barreessuunis yeroo hunda ni danda''ama.$$,
'["sagalee","dubbachuu","maaykiroofoonii"]', FALSE),
('read-aloud','om','accessibility','Gaaffiiwwan dhaggeeffachuu',
$$Gaaffiin ykn ergaan sagaleedhaan akka dubbifamu "Dhaggeeffadhu" filadhaa. Yeroo kamiyyuu dhaabuu, itti fufuu fi xumuruu dandeessu. Bilbilli keessan sagalee afaan keessaniif hin qabu yoo ta''e, barreeffamni fuula irra ni hafa.$$,
'["dhaggeeffachuu","sagalee","dhaabuu"]', FALSE),
('accessibility-settings','om','accessibility','Qindaa''ina dhaqqabummaa jijjiiruu',
$$"Qindaa''ina dhaqqabummaa" banaa: barreeffama guddisuu, wal-dorgommii halluu olaanaa banuu, jechoota salphaa fayyadamuu, sochii hir''isuu ykn afaan filachuu dandeessu. Jijjiiramni battalumatti hojii irra oola.$$,
'["qindaa''ina","barreeffama","salphaa","afaan"]', FALSE),
('identity-options','om','identity','Yoo eenyummaa biyyaalessaa hin qabaanne',
$$Waraqaa eenyummaa ganda, paaspoortii, eenyummaa baqataa ykn sanada biraa fayyadamuu dandeessu. Sanadni yoo hin jiraanne, dhaabbanni michuu isin akeekuu danda''a, ykn "Na akeeki" filachuu dandeessu. Filannoon hundi hojjettoota leenji''aniin ni mirkanaa''a.$$,
'["eenyummaa","sanada","baqataa","paaspoortii","akeekuu"]', FALSE),
('private-support','om','support','Deeggarsa dhuunfaa gaafachuu',
$$Ragaa yaalaa malee yeroo kamiyyuu gargaarsa gaafachuu dandeessu. Maaltu isin gargaaru fi akkamitti akka isin quunnamnu nutti himaa. Gaaffii keessan kan dubbisuu danda''an hojjettoota deeggarsaa ACCESSFLOW qofa. Namni tokko isiniif deebisa.$$,
'["gargaarsa","deeggarsa","nama"]', FALSE),
('save-and-resume','om','progress','Olkaa''uu fi booda itti fufuu',
$$Deebiin keessan otoo hojjettanuu ofumaan olkaa''ama. Walqunnamtiin yoo citu, deebiin keessan meeshaa kana irratti hafee yeroo deebitanii walqunnamtan ni ergama. Booda itti fufuuf deebitanii seenaa "Itti fufi" filadhaa.$$,
'["olkaa''uu","itti fufuu","booda","interneetii"]', FALSE),
('applying-for-jobs','om','application','Hojiif iyyachuu',
$$Hojii banaatii "Iyyadhu" filadhaa. Deebiiwwan tokko tokko piroofaayilii keessan irraa guutamu; jijjiiruu dandeessu. Qacaraan kutaa piroofaayilii keessanii kam akka argu isin filattu. Erguun dura deebii hunda ni ilaaltu.$$,
'["iyyachuu","iyyata","hojii","erguu"]', FALSE),
('fixing-errors','om','errors','Yoo deebiin rakkoo qabaate',
$$Deebiin sirreeffamuu yoo qabaate, ergaan maal jijjiiruu akka qabdan ibsu gaaffii jala ni mul''ata. Deebii jijjiiraatii ammas "Itti aanu" filadhaa. Yoo rakkattan "Gargaarsa argadhu" filadhaa.$$,
'["dogoggora","rakkoo","sirreessuu"]', FALSE),
('job-support-filter','om','jobs','Hojii deeggarsa barbaaddan qabu argachuu',
$$Fuula hojiiwwanii irratti deeggarsa bakka hojii kan akka afaan mallattoo, mana irraa hojjechuu ykn deeggarsa dubbisaa iskiriinii filachuu dandeessu. Calaltuun kun dhuunfaa dha; hin olkaa''amu, qacaraanis hin argu.$$,
'["calaltuu","deeggarsa","afaan mallattoo","hojii"]', FALSE),

-- Somali (draft translation)
('how-registration-works','so','registration','Sida diiwaangelintu u shaqeyso',
$$Diiwaangelintu waxay ku weydiinaysaa hal su'aal markiiba. Ka jawaab su'aasha, kadibna dooro "Xiga". Wakhti kasta dib ayaad u noqon kartaa si aad jawaabta u beddesho. Dhammaadka waxaad arki doontaa dhammaan jawaabahaaga waxaadna beddeli kartaa ka hor intaadan dhammayn. Ma jiro xad wakhti.$$,
'["diiwaangelin","isdiiwaangeli","akoon","su''aal","xiga"]', FALSE),
('why-we-ask','so','privacy','Sababta aan u weydiinno macluumaad shakhsi ah',
$$Waxaan kaliya weydiinnaa macluumaadka kaa caawinaya inaad akoon samayso, shaqo codsato ama taageero hesho. Su'aal kastaa waxay leedahay qoraal "Sababta aan u weydiinno". Su'aalaha "ikhtiyaari" ah waad ka boodi kartaa. Weligeen ma weydiinno baaritaan caafimaad.$$,
'["sababta","shakhsi","macluumaad","ikhtiyaari"]', FALSE),
('your-privacy','so','privacy','Asturnaantaada iyo waxa loo shaqeeyaha arko',
$$Loo shaqeeyayaashu waxay arkaan oo kaliya qaybaha astaantaada aad dooratay inaad la wadaagto marka aad codsato. Doorashooyinkaaga taageerada iyo codsiyadaada taageerada gaarka ah looma muujiyo loo shaqeeyayaasha. Waad soo dejisan kartaa ama tirtiri kartaa xogtaada.$$,
'["asturnaan","wadaag","loo shaqeeye","tirtir"]', FALSE),
('voice-input','so','voice','Isticmaalka codka',
$$Dooro "Ku hadal jawaabtaada" su'aasha agteeda oo si cad u hadal. Erayadaadu waxay u muuqdaan qoraal si aad u hubiso una saxdo. Waxba lama kaydiyo ilaa aad doorato "Isticmaal qoraalkan". Qorista sidoo kale had iyo jeer way shaqaysaa.$$,
'["cod","hadal","makarafoon"]', FALSE),
('read-aloud','so','accessibility','Dhegeysiga su''aalaha',
$$Dooro "Dhageyso" si su'aal ama fariin kor loogu akhriyo. Wakhti kasta waad joojin kartaa, sii wadi kartaa oo dhammayn kartaa. Haddii taleefankaagu uusan lahayn cod luqaddaada ah, qoraalku shaashadda ayuu ku hadhayaa.$$,
'["dhageyso","cod","jooji"]', FALSE),
('accessibility-settings','so','accessibility','Beddelka dejinta helitaanka',
$$Fur "Dejinta helitaanka" si aad qoraalka u weyneyso, u shido iska-horimaad sare, u isticmaasho erayo fudud, u yareyso dhaqdhaqaaqa ama u doorato luqaddaada. Isbeddelada isla markiiba way dhaqan galaan waana la kaydiyaa.$$,
'["dejin","qoraal","fudud","luqad"]', FALSE),
('identity-options','so','identity','Haddii aadan haysan aqoonsi qaran',
$$Waxaad isticmaali kartaa aqoonsiga kebele, baasaboor, aqoonsiga qaxootiga ama dukumeenti kale. Haddii aadan haysan dukumeenti, urur la-shaqeeye ah ayaa ku gudbin kara, ama waxaad dooran kartaa "I gudbi". Doorasho kasta waxaa hubiya shaqaale tababaran.$$,
'["aqoonsi","dukumeenti","qaxooti","baasaboor","gudbin"]', FALSE),
('private-support','so','support','Codsashada taageero gaar ah',
$$Wakhti kasta waad codsan kartaa caawimaad la'aanteed caddayn caafimaad. Noo sheeg waxa ku caawin lahaa iyo sida aan kuula soo xiriirno. Shaqaalaha taageerada ACCESSFLOW oo kaliya ayaa akhrin kara codsigaaga. Qof ayaa kuu jawaabi doona.$$,
'["caawimaad","taageero","qof"]', FALSE),
('save-and-resume','so','progress','Kaydin iyo sii wadid dambe',
$$Jawaabahaaga si toos ah ayaa loo kaydiyaa inta aad shaqaynayso. Haddii xiriirku go'o, jawaabahaagu qalabkan ayay ku hadhayaan waxaana la diri doonaa marka aad dib u xiriirto. Si aad dambe u sii wadato, dib u gal oo dooro "Sii wad".$$,
'["kaydi","sii wad","dambe","internet"]', FALSE),
('applying-for-jobs','so','application','Codsashada shaqo',
$$Fur shaqo oo dooro "Codso". Jawaabaha qaarkood waxaa laga buuxiyaa astaantaada; waad beddeli kartaa. Adiga ayaa dooranaya qaybaha uu loo shaqeeyuhu arko. Ka hor dirista waxaad dib u eegaysaa jawaab kasta.$$,
'["codso","codsi","shaqo","dir"]', FALSE),
('fixing-errors','so','errors','Marka jawaab dhibaato leedahay',
$$Haddii jawaab u baahan tahay sixid, fariin sharxaysa waxa la beddelayo ayaa ka muuqanaysa su'aasha hoosteeda. Beddel jawaabta oo mar kale dooro "Xiga". Haddii aad ku xayirantahay, dooro "Hel caawimaad".$$,
'["khalad","dhibaato","sixid"]', FALSE),
('job-support-filter','so','jobs','Helitaanka shaqooyin leh taageerada aad u baahan tahay',
$$Bogga shaqooyinka waxaad ku shaandhayn kartaa taageerada goobta shaqada, sida luqadda calaamadaha, ka shaqaynta guriga ama taageerada akhriyaha shaashadda. Shaandhayntani waa gaar; lama kaydiyo, loo shaqeeyayaashuna ma arkaan.$$,
'["shaandhayn","taageero","luqadda calaamadaha","shaqo"]', FALSE),

-- Tigrinya (draft translation)
('how-registration-works','ti','registration','ምዝገባ ብኸመይ ይሰርሕ',
$$ምዝገባ ሓደ ሕቶ ብሓደ ግዜ ይሓትት። ነቲ ሕቶ መልሱ፣ ድሕሪኡ "ቀጺሉ" ምረጹ። ኣብ ዝኾነ ግዜ ናብ ድሕሪት ተመሊስኩም መልስኹም ክትቕይሩ ትኽእሉ ኢኹም። ኣብ መወዳእታ ኩሉ መልስታትኩም ርእዮም ቅድሚ ምውዳእኩም ክትቕይሩ ትኽእሉ። ገደብ ግዜ የለን።$$,
'["ምዝገባ","ሕሳብ","ሕቶ","ቀጺሉ"]', FALSE),
('why-we-ask','ti','privacy','ስለምንታይ ውልቃዊ ሓበሬታ ንሓትት',
$$ሕሳብ ንምፍጣር፣ ንስራሕ ንምምልካት ወይ ደገፍ ንምርካብ ዝሕግዝ ሓበሬታ ጥራይ ኢና ንሓትት። ነፍሲ ወከፍ ሕቶ "ስለምንታይ ንሓትት" ዝብል መግለጺ ኣለዎ። "ኣማራጺ" ዝተባህሉ ሕቶታት ክትሓልፍዎም ትኽእሉ ኢኹም። ውጽኢት ሕክምናዊ መርመራ ፈጺምና ኣይንሓትትን።$$,
'["ስለምንታይ","ውልቃዊ","ሓበሬታ","ኣማራጺ"]', FALSE),
('your-privacy','ti','privacy','ብሕትውናኹም ከምኡውን ኣስራሕቲ ዝርእይዎ',
$$ኣስራሕቲ ክትምልከቱ ከለኹም ክርእይዎ ዝመረጽኩምዎ ክፍልታት መግለጺኹም ጥራይ እዮም ዝርእዩ። ምርጫታት ደገፍኩምን ናይ ብሕቲ ሕቶታት ደገፍኩምን ንኣስራሕቲ ኣይርኣዩን። ሓበሬታኹም ከተውርዱ ወይ ክትድምስሱ ትኽእሉ ኢኹም።$$,
'["ብሕትውና","ምክፋል","ኣስራሒ","ምድምሳስ"]', FALSE),
('voice-input','ti','voice','ብድምጺ ምምላስ',
$$ኣብ ጥቓ እቲ ሕቶ "መልስኹም ተዛረቡ" ምረጹን ብንጹር ተዛረቡን። ቃላትኩም ከም ጽሑፍ ይረኣዩ፤ ከተረጋግጹን ከተዕርዩን ትኽእሉ። "ነዚ ጽሑፍ ተጠቐም" ክሳብ ትመርጹ ዋላ ሓንቲ ኣይዕቀብን። ምጽሓፍ ውን ኩሉ ግዜ ይከኣል።$$,
